window.SNToolsUtils = class SNToolsUtils {
  isJSONObject(str) {
    if (typeof str !== 'string') return false;

    try {
      const parsed = JSON.parse(str);
      return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed);
    } catch (e) {
      return false;
    }
  }
}

